func HasProblemWith(preds ...predicate.Problem) predicate.ContestProblemResult {
	return predicate.ContestProblemResult(func(s *sql.Selector) {
		step := newProblemStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasContestProblem applies the HasEdge predicate on the "contest_problem" edge.
func HasContestProblem() predicate.ContestProblemResult {
	return predicate.ContestProblemResult(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, ContestProblemTable, ContestProblemColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

