// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ContestProblemResult) predicate.ContestProblemResult {
	return predicate.ContestProblemResult(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ContestProblemResult) predicate.ContestProblemResult {
	return predicate.ContestProblemResult(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ContestProblemResult) predicate.ContestProblemResult {
	return predicate.ContestProblemResult(sql.NotPredicates(p))
}
